// Package scriptjs runs the TitanView TitanScript VM (the same TypeScript runtime the browser uses) inside Go
// through goja, so the alert engine can evaluate indicator, strategy and alertcondition alerts while no
// browser is open. script_bundle.js is generated by `node scripts/build-script-server.mjs` from
// frontend/src/script/serverEntry.ts; a frontend test fails when the committed bundle is stale.
package scriptjs

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"sync"
	"time"
	_ "time/tzdata" // IANA zones (Europe/Istanbul, America/New_York) even in slim containers

	"github.com/dop251/goja"
	"github.com/ersincebi/titanview/backend/internal/domain"
)

//go:embed script_bundle.js
var bundleSrc string

// polyfill supplies what goja lacks compared to a browser: performance.now, console and the slice of
// Intl.DateTimeFormat the script runtime uses (formatToParts with an IANA timeZone).
const polyfill = `
var performance = { now: function () { return Date.now(); } };
var console = { log: function () {}, warn: function () {}, error: function () {}, info: function () {} };
var Intl = {
  DateTimeFormat: function (locale, opts) {
    var tz = (opts && opts.timeZone) || 'UTC';
    if (!__tzValid(tz)) throw new RangeError('Invalid time zone specified: ' + tz);
    this.formatToParts = function (d) { return __tzParts(tz, d.getTime()); };
    this.format = function (d) {
      var p = __tzParts(tz, d.getTime()), o = {};
      for (var i = 0; i < p.length; i++) o[p[i].type] = p[i].value;
      return o.month + '/' + o.day + '/' + o.year + ', ' + o.hour + ':' + o.minute + ':' + o.second;
    };
  }
};
`

// Input mirrors ServerRunInput in serverEntry.ts.
type Input struct {
	Code          string                     `json:"code"`
	Candles       []domain.Candle            `json:"candles"`
	Symbol        string                     `json:"symbol,omitempty"`
	Timeframe     string                     `json:"timeframe,omitempty"`
	Mintick       float64                    `json:"mintick,omitempty"`
	Inputs        map[string]json.RawMessage `json:"inputs,omitempty"`
	Scripts          []Script                   `json:"scripts,omitempty"`
	SymbolCandles    map[string][]domain.Candle `json:"symbolCandles,omitempty"`
	MagnifierCandles []domain.Candle            `json:"magnifierCandles,omitempty"`
}

// Script is a saved script offered to the library resolver (`import user/lib/1`).
type Script struct {
	Name string `json:"name"`
	Code string `json:"code"`
}

// Plot is one plot() series aligned to the input candles (nil = na).
type Plot struct {
	ID     string     `json:"id"`
	Title  string     `json:"title"`
	Values []*float64 `json:"values"`
}

// Alert is one alert()/alertcondition() firing on the last bar.
type Alert struct {
	Time    int64  `json:"time"`
	Message string `json:"message"`
	Kind    string `json:"kind,omitempty"`
	Title   string `json:"title,omitempty"`
	Freq    string `json:"freq,omitempty"`
}

// Condition is a declared alertcondition() (title + default message), even when false.
type Condition struct {
	Title   string `json:"title"`
	Message string `json:"message"`
}

// Fill is one strategy order fill.
type Fill struct {
	Time         int64   `json:"time"`
	Action       string  `json:"action"`
	Qty          float64 `json:"qty"`
	Price        float64 `json:"price"`
	ID           string  `json:"id"`
	Comment      string  `json:"comment"`
	PositionSize float64 `json:"positionSize"`
}

// Output mirrors ServerRunOutput in serverEntry.ts.
type Output struct {
	OK              bool        `json:"ok"`
	Error           string      `json:"error,omitempty"`
	Title           string      `json:"title"`
	IsStrategy      bool        `json:"isStrategy"`
	Plots           []Plot      `json:"plots"`
	Alerts          []Alert     `json:"alerts"`
	AlertConditions []Condition `json:"alertConditions"`
	Fills           []Fill      `json:"fills"`
	MissingSymbols  []string    `json:"missingSymbols,omitempty"`
	ExecutionMs     float64     `json:"executionMs"`
}

// PlotValue returns the plot value at bar i by title or id ("plot_0" style ids included); ok=false for na.
func (o *Output) PlotValue(ref string, i int) (float64, bool) {
	p := o.FindPlot(ref)
	if p == nil || i < 0 || i >= len(p.Values) || p.Values[i] == nil {
		return 0, false
	}
	return *p.Values[i], true
}

// FindPlot resolves a plot by exact title, id, or "plot_N" positional reference.
func (o *Output) FindPlot(ref string) *Plot {
	for i := range o.Plots {
		if o.Plots[i].Title == ref || o.Plots[i].ID == ref {
			return &o.Plots[i]
		}
	}
	var n int
	if _, err := fmt.Sscanf(ref, "plot_%d", &n); err == nil && n >= 0 && n < len(o.Plots) {
		return &o.Plots[n]
	}
	return nil
}

var (
	compileOnce sync.Once
	program     *goja.Program
	compileErr  error
)

func compiled() (*goja.Program, error) {
	compileOnce.Do(func() {
		program, compileErr = goja.Compile("script_bundle.js", polyfill+bundleSrc+"\n;TitanScriptServer.run;", false)
	})
	return program, compileErr
}

// Runner owns one goja runtime (goja runtimes are not goroutine-safe). Use a Pool for concurrency.
type Runner struct {
	vm  *goja.Runtime
	run goja.Callable
}

// NewRunner compiles (once per process) and instantiates the script bundle.
func NewRunner() (*Runner, error) {
	prog, err := compiled()
	if err != nil {
		return nil, fmt.Errorf("script bundle compile: %w", err)
	}
	vm := goja.New()
	if err := vm.Set("__tzValid", tzValid); err != nil {
		return nil, err
	}
	if err := vm.Set("__tzParts", func(tz string, ms float64) []map[string]string { return tzParts(tz, int64(ms)) }); err != nil {
		return nil, err
	}
	v, err := vm.RunProgram(prog)
	if err != nil {
		return nil, fmt.Errorf("script bundle init: %w", err)
	}
	fn, ok := goja.AssertFunction(v)
	if !ok {
		return nil, errors.New("script bundle: TitanScriptServer.run is not a function")
	}
	return &Runner{vm: vm, run: fn}, nil
}

// Run executes one script. Timeout interrupts runaway scripts (infinite while loops).
func (r *Runner) Run(in Input, timeout time.Duration) (*Output, error) {
	raw, err := json.Marshal(in)
	if err != nil {
		return nil, err
	}
	if timeout > 0 {
		t := time.AfterFunc(timeout, func() { r.vm.Interrupt("script: zaman aşımı") })
		defer func() {
			t.Stop()
			r.vm.ClearInterrupt()
		}()
	}
	v, err := r.run(goja.Undefined(), r.vm.ToValue(string(raw)))
	if err != nil {
		var ie *goja.InterruptedError
		if errors.As(err, &ie) {
			return nil, fmt.Errorf("script: betik %s içinde bitmedi", timeout)
		}
		return nil, fmt.Errorf("script: %w", err)
	}
	var out Output
	if err := json.Unmarshal([]byte(v.String()), &out); err != nil {
		return nil, fmt.Errorf("script output: %w", err)
	}
	return &out, nil
}

// Pool hands out runners to concurrent callers (lazily created, at most size).
type Pool struct {
	ch chan *Runner
	mu sync.Mutex
	n  int
	sz int
}

// NewPool creates a pool of at most size runners.
func NewPool(size int) *Pool {
	if size < 1 {
		size = 1
	}
	return &Pool{ch: make(chan *Runner, size), sz: size}
}

// Run borrows a runner, executes and returns it.
func (p *Pool) Run(in Input, timeout time.Duration) (*Output, error) {
	r, err := p.get()
	if err != nil {
		return nil, err
	}
	out, runErr := r.Run(in, timeout)
	p.ch <- r
	return out, runErr
}

func (p *Pool) get() (*Runner, error) {
	select {
	case r := <-p.ch:
		return r, nil
	default:
	}
	p.mu.Lock()
	if p.n < p.sz {
		p.n++
		p.mu.Unlock()
		r, err := NewRunner()
		if err != nil {
			p.mu.Lock()
			p.n--
			p.mu.Unlock()
			return nil, err
		}
		return r, nil
	}
	p.mu.Unlock()
	return <-p.ch, nil
}

func tzValid(tz string) bool {
	_, err := time.LoadLocation(tz)
	return err == nil
}

var weekdays = [...]string{"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"}

func tzParts(tz string, ms int64) []map[string]string {
	loc, err := time.LoadLocation(tz)
	if err != nil {
		loc = time.UTC
	}
	t := time.UnixMilli(ms).In(loc)
	part := func(typ, val string) map[string]string { return map[string]string{"type": typ, "value": val} }
	return []map[string]string{
		part("weekday", weekdays[t.Weekday()]),
		part("month", fmt.Sprintf("%02d", int(t.Month()))),
		part("day", fmt.Sprintf("%02d", t.Day())),
		part("year", fmt.Sprintf("%04d", t.Year())),
		part("hour", fmt.Sprintf("%02d", t.Hour())),
		part("minute", fmt.Sprintf("%02d", t.Minute())),
		part("second", fmt.Sprintf("%02d", t.Second())),
	}
}
